import hashlib, importlib, json, sys
sys.path.insert(0, "scripts")
m = importlib.import_module("c5_excess_two_c44_input_audit")
saved_bytes = m.OUTPUT.read_bytes()
saved = json.loads(saved_bytes)
computed = m.audit()
computed_bytes = m.encoded(computed)
differences = []
def walk(a, b, path="$"):
    if type(a) is not type(b):
        differences.append({"path":path, "saved":a, "computed":b})
    elif isinstance(a, dict):
        for key in sorted(set(a) | set(b)):
            if key not in a or key not in b:
                differences.append({"path":path+"."+str(key), "saved":a.get(key), "computed":b.get(key)})
            else:
                walk(a[key], b[key], path+"."+str(key))
    elif isinstance(a, list):
        if len(a) != len(b):
            differences.append({"path":path+".length", "saved":len(a), "computed":len(b)})
        for idx,(x,y) in enumerate(zip(a,b)):
            walk(x,y,path+"["+str(idx)+"]")
    elif a != b:
        differences.append({"path":path, "saved":a, "computed":b})
walk(saved, computed)
print(json.dumps({"saved_sha256":hashlib.sha256(saved_bytes).hexdigest(),"computed_sha256":hashlib.sha256(computed_bytes).hexdigest(),"saved_bytes":len(saved_bytes),"computed_bytes":len(computed_bytes),"difference_count":len(differences),"differences":differences}, indent=2, sort_keys=True))
